import {main as readTracker} from './read_mumbai_nurture_dashboard.ts';

// PUBLIC_ASSETS_START
const CSS_BASE64='';
const JS_BASE64='';
// PUBLIC_ASSETS_END

type Query=Record<string,string|string[]|undefined>;
export async function preprocessor(event:{kind:string;query?:Query;headers?:Record<string,string|string[]|undefined>}) {
  const headers=event.headers||{};
  const code=Object.entries(headers).find(([key])=>key.toLowerCase()==='x-mumbai-churn-passcode')?.[1];
  return {query:event.kind==='http'?(event.query||{}):{},
    dashboard_passcode:event.kind==='http'?(Array.isArray(code)?code[0]:code||''):''};
}

/** Public shell only. Data is served only after the reader's server-side gate. */
export async function main(query:Query={},dashboard_passcode:string='') {
  if(query.__data==='1') {
    const result=await readTracker(dashboard_passcode);
    return {windmill_content_type:'application/json; charset=utf-8',result,
      windmill_headers:{'Cache-Control':'no-store, private','X-Robots-Tag':'noindex, nofollow'}};
  }
  const css=Buffer.from(CSS_BASE64,'base64').toString('utf8');
  const js=Buffer.from(JS_BASE64,'base64').toString('utf8').replaceAll('</script','<\\/script');
  return {windmill_content_type:'text/html; charset=utf-8',
    windmill_headers:{'Cache-Control':'no-store','X-Robots-Tag':'noindex, nofollow'},
    result:`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><title>Mumbai churn tracker · Beforest</title><style>${css}</style></head><body><div id="root"></div><script type="module">${js}</script></body></html>`};
}
